// === Tab: sketch.js ===
// parameters to be controlled
const controls = {
  sigma: 10,
  rho: 28,
  beta: 8.0 / 3.0,
  t: 0.01,
  partNum: 400,
  fov: .7,
  partSize: 1,
  outlines: false,
  view: "rotate",
  trace: false,
  spread: 5,
  spawnPoint: {x: 10, y: -9, z: 0},
  // --- NEW CONTROLS ---
  partColor: {r: 0, g: 255, b: 255},
  bgColor: {r: 0, g: 0, b: 0}
}

let paused = false;
let fpsGraph;
let clock = -600; 
let fov; 
let scaleFactor = 4;
let scaleFactorTail = scaleFactor * 1; 

const particles = [];

class particle {
  constructor(x, y, z, color) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.color = color;
    this.dir = createVector(0, 0, 0);
  }

  update(sigma, rho, beta, t) {
    let dx = sigma * (this.y - this.x);
    let dy = this.x * (rho - this.z) - this.y;
    let dz = this.x * this.y - beta * this.z;
    this.x += dx * t;
    this.y += dy * t;
    this.z += dz * t;
    this.dir.set(dx * t, dy * t, dz * t);
  }

  draw() {
    let initVec = createVector(1, 5, 2);
    push();
    translate(this.x * scaleFactor, this.y * scaleFactor, this.z * scaleFactor);
    rotate(abs(initVec.angleBetween(this.dir)), initVec.cross(this.dir));
    translate(-this.dir.mag() * scaleFactorTail / 2, 0, 0);

    // Use the color assigned at creation
    fill(this.color);
    box(max(this.dir.mag() * scaleFactorTail, controls.partSize), controls.partSize, controls.partSize);
    pop();
  }
}

function createParticles(number) {
  for(let i = 0; i < number; i++) {
    // UPDATED: Now uses the color from the controls
    let pCol = color(controls.partColor.r, controls.partColor.g, controls.partColor.b);

    particles.push(new particle(
      random(-1, 1) * max(controls.spread, .000000001) + controls.spawnPoint.x,
      random(-1, 1) * max(controls.spread, .000000001) - controls.spawnPoint.y,
      random(-1, 1) * max(controls.spread, .000000001) + controls.spawnPoint.z + 27,
      pCol));
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function setup() {
  pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);

  const controlsContainer = createDiv();
  controlsContainer.id("controlsContainer");
  controlsContainer.style("position", "fixed");
  controlsContainer.style("top", "10px");
  controlsContainer.style("right", "10px");
  controlsContainer.style("width", "300px");

  const pane = new Tweakpane.Pane({container: document.getElementById("controlsContainer"), title: "controls", expanded: true});
  pane.registerPlugin(TweakpaneEssentialsPlugin);

  pane.addSeparator();
  const pauseBtn = pane.addButton({title: "pause"});
  pauseBtn.on("click", () => {
    paused = !paused;
    pauseBtn.title = paused ? "resume" : "pause";
  });

  pane.addSeparator();

  // --- ADDED COLOR PICKERS ---
  pane.addInput(controls, "partColor", { label: "particle color" }).on("change", () => {
    // Update existing particles to the new color immediately
    let newCol = color(controls.partColor.r, controls.partColor.g, controls.partColor.b);
    particles.forEach(p => p.color = newCol);
  });

  pane.addInput(controls, "bgColor", { label: "background" });

  pane.addInput(controls, "t", {label: "time step", min: 0.0001, max: 0.01});
  pane.addInput(controls, "partNum", {label: "particle number", min: 1, max: 1000, step: 1}).on("change", () => {
    if(controls.partNum > particles.length) {
      createParticles(controls.partNum - particles.length);
    } else {
      let dif = particles.length - controls.partNum;
      for(let i = 0; i < dif; i++) { particles.shift(); }
    }
  });

  pane.addInput(controls, "fov", {label: "field of view", min: .1, max: 2, step: .1});
  pane.addInput(controls, "partSize", {label: "particle size", min: 1, max: 30, step: 1});
  pane.addInput(controls, "outlines", {label: "draw outlines"});
  pane.addInput(controls, "trace");
  pane.addInput(controls, "view", {options: {rotate: "rotate", top: "top", bottom: "bottom", side: "side"}}).on("change", () => {
    background(controls.bgColor.r, controls.bgColor.g, controls.bgColor.b);
  });

  pane.addSeparator();
  pane.addButton({title: "respawn particles"}).on("click", () => {
    background(controls.bgColor.r, controls.bgColor.g, controls.bgColor.b);
    particles.length = 0;
    createParticles(controls.partNum);
  })

  pane.addInput(controls, "spread");
  pane.addInput(controls, "spawnPoint", {label: "spawn point", x: {min: -30, max: 30}, y: {min: -30, max: 30}, z: {min: -30, max: 30}});

  const stats = pane.addFolder({title: "stats", expanded: false});
  fpsGraph = stats.addBlade({view: "fpsgraph", label: "fps"});

  createParticles(controls.partNum);
}

function draw() {
  fpsGraph.begin();

  if(!paused) {
    // UPDATED: Use dynamic background color
    if(!controls.trace) {
      background(controls.bgColor.r, controls.bgColor.g, controls.bgColor.b);
    }

    switch(controls.view) {
      case "rotate":
        if(!controls.trace) {
          push();
          stroke(255, 64);
          noFill();
          box(60 * scaleFactor);
          pop();
        }
        camera(sin(clock / 360) * 100 * scaleFactor, cos(clock / 360) * 100 * scaleFactor, 0, 0, 0, 0, 0, 0, -1);
        perspective(controls.fov, width / height);
        break;
      case "top":
        camera(0, 0, 212 * scaleFactor, 0, 0, 0, 0, 1, 0);
        perspective(controls.fov, width / height);
        break;
      case "bottom":
        camera(0, 0, -212 * scaleFactor, 0, 0, 0, 0, 1, 0);
        perspective(controls.fov, width / height);
        break;
      case "side":
        camera(150 * scaleFactor, -150 * scaleFactor, 0, 0, 0, 0, 0, 0, -1);
        perspective(controls.fov, width / height);
        break;
    }

    push();
    if(controls.outlines) {
      stroke(64);
      strokeWeight(0.66);
    } else {
      noStroke();
    }
    translate(0, 0, -27 * scaleFactor);
    for(let p of particles) {
      p.update(controls.sigma, controls.rho, controls.beta, controls.t);
      p.draw();
    }
    pop();
    clock++;
  }
  fpsGraph.end();
}

